int _Steps = 20;
float _Smoothness = 0.05; 
float _Seed = 500.0;
float _DisplacementScale = 0.1; 
float _DisplacementSpread = 10.0;

vec3 Hash(vec2 p)
{
	vec3 q = vec3( dot(p,vec2(127.1,311.7)), dot(p,vec2(269.5,183.3)), dot(p,vec2(419.2,371.9)) );
	return fract(sin(q)*43758.5453);
}

vec3 Noise(vec2 p)
{
	vec2 ip = floor(p);
	vec2 u = fract(p);
	u = u*u*(3.0-2.0*u);
	vec3 res = mix(mix(Hash(ip),Hash(ip+vec2(1,0)),u.x), mix(Hash(ip+vec2(0,1)),Hash(ip+vec2(1,1)),u.x),u.y);
	return res*res;
}

vec3 FBM(vec2 x)
{
	vec3 v = vec3 (0.0);
	vec3 a = vec3 (0.5);
	mat2 rot = mat2(0.87, 0.48, -0.48, 0.87);
	for (int i = 0; i < 6; ++i) 
	{
		v += a * Noise(x);
		x = (x * 2.0 + vec2(100,100)) * rot;
		a *= 0.5;
	}
	return v;
}

vec3 HeightMap (vec2 uv)
{
	return FBM(_DisplacementSpread * uv);
}

float RockSDF (vec3 p, int steps, float seed, float smoothness) 
{
	float d = length(p) - 0.95;
	for(int i = 0; i < steps; i++)
	{
		float j = float(i) + seed;
		float r = 2.5 + fract(sin(j * 727.1)*435.545);
		vec3 v = normalize(fract(sin(vec3(127.231, 491.7, 718.423) * j) * 435.543) * 2.0 - 1.0);
		float a = d;
		float b = length(p + v * r) - r * 0.8;
		float k = smoothness;
		float h = clamp(0.5 + 0.5 * (-b - a) / k, 0.0, 1.0);
		d = mix(a, -b, h) + k * h * (1.0 - h);
	}
	return d;
}

float Map (vec3 p)
{
	return RockSDF(p, _Steps, floor(iTime) * 10.0, _Smoothness);
}

vec3 NormalMap( vec3 p )
{
	vec2 eps = vec2(0.0001, 0.0);
	vec3 result = vec3(0,0,0);
	result.x = Map(p + eps.xyy) - Map(p - eps.xyy);
	result.y = Map(p + eps.yxy) - Map(p - eps.yxy);
	result.z = Map(p + eps.yyx) - Map(p - eps.yyx);
	return normalize(result);
}

vec3 Surface3D( vec3 p, vec3 n )
{
	n = max(n * n, 0.01);
	n /= (n.x + n.y + n.z );
	return (HeightMap(p.yz) * n.x + HeightMap(p.zx) * n.y + HeightMap(p.xy) * n.z).xyz;
}

vec2 ScalarField (vec3 p)
{
    p = p * 2.0;
    float offset = length(Surface3D(p,NormalMap(p)));
	return vec2(Map(p) + _DisplacementScale * offset, offset);
}

vec4 Lighting (vec3 p, float e)
{
    vec4 a = vec4 (0.2,0.2,0.2,1.0);  
    vec4 b = vec4(1,1,1,0); 
    vec3 l = normalize(vec3(10,10,10)); 
    float c = (ScalarField(p+l*e).x-ScalarField(p).x)/e; 
    return clamp(c,0.0,1.0)*b+a; 
}

vec4 Raymarching (vec3 p, vec3 rd)
{
    vec3 n = p;
    for (int i=0; i<100; i++)
    {
      float t = ScalarField(p).x;
      if (t<0.01)  
      {
          float k = ScalarField(p).y;
          return vec4(k,k,k,1.0) * Lighting (p, 0.01);  
      }
      p+=t*rd;
    }
    return vec4(0.0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 uv = (2. * fragCoord.xy - iResolution.xy) / iResolution.y;
	fragColor = Raymarching(vec3 (0,0,-0.999),normalize(vec3(uv,2.)));
}
